172	    /// Map the writer to a new type.
173	    pub fn map_writer<W2>(self, map: impl FnOnce(Lens) -> W2) -> SelectorScope<W2> {
174	        SelectorScope {
175	            path: self.path,
176	            store: self.store,
177	            write: map(self.write),
