/// A single node in the [`StoreSubscriptions`] tree. Each path is a specific view into the store
/// and can be subscribed to and marked dirty separately.
///
/// Each node tracks two kinds of subscribers:
/// - **shallow** subscribers only care about writes to this exact path.
/// - **deep** subscribers care about writes to this path *or any of its descendants*. This is what
///   makes reading a parent value reactive to changes in a nested child field.
#[derive(Clone, Default)]
pub(crate) struct SelectorNode {
    /// Subscribers that only want to be notified when this exact path is marked dirty.
    shallow_subscribers: HashSet<ReactiveContext>,
    /// Subscribers that want to be notified when this path or any descendant path is marked dirty.
    deep_subscribers: HashSet<ReactiveContext>,
    root: HashMap<PathKey, SelectorNode>,
}

impl SelectorNode {
    /// Get an existing selector node by its path.
    fn get(&self, path: &[PathKey]) -> Option<&SelectorNode> {
        let [first, rest @ ..] = path else {
            return Some(self);
        };
        self.root.get(first).and_then(|child| child.get(rest))
    }

    /// Get an existing selector node by its path mutably.
    fn get_mut(&mut self, path: &[PathKey]) -> Option<&mut SelectorNode> {
        let [first, rest @ ..] = path else {
            return Some(self);
        };
        self.root
            .get_mut(first)
            .and_then(|child| child.get_mut(rest))
    }

    /// Get a selector mutably or create one if it doesn't exist. This is used when subscribing to
    /// a path that may not exist yet.
    fn get_mut_or_default(&mut self, path: &[PathKey]) -> &mut SelectorNode {
        let [first, rest @ ..] = path else {
            return self;
        };
        self.root
            .entry(*first)
            .or_default()
            .get_mut_or_default(rest)
    }

    /// True if this node holds no subscribers and no children, so it can be pruned from the tree.
    fn is_empty(&self) -> bool {
        self.shallow_subscribers.is_empty()
            && self.deep_subscribers.is_empty()
            && self.root.is_empty()
    }

    /// Collect every subscriber (shallow and deep) on this node and all of its descendants into `out`.
    ///
    /// This is used when a path is marked dirty recursively: every subscriber in the subtree needs
    /// to be notified because the value they view may have changed.
    #[allow(clippy::mutable_key_type)]
    fn collect_subtree(&self, out: &mut HashSet<ReactiveContext>) {
        out.extend(self.shallow_subscribers.iter().cloned());
        out.extend(self.deep_subscribers.iter().cloned());
        for child in self.root.values() {
            child.collect_subtree(out);
        }
    }

    /// Remove a path from the subscription tree
    fn remove(&mut self, path: &[PathKey]) {
        let [first, rest @ ..] = path else {
            return;
        };
        if let Some(node) = self.root.get_mut(first) {
            if rest.is_empty() {
                self.root.remove(first);
            } else {
                node.remove(rest);
            }
        }
    }

    /// Remove the given reactive contexts from this node and all descendants, pruning any node that
    /// becomes empty as a result. Returns true if this node is now empty.
    fn remove_dead(&mut self, dead: &[ReactiveContext]) -> bool {
        self.shallow_subscribers.retain(|rc| !dead.contains(rc));
        self.deep_subscribers.retain(|rc| !dead.contains(rc));
        self.root.retain(|_, child| !child.remove_dead(dead));
        self.is_empty()
    }
}

